CREATE TABLE "Players"."Bowling_stats" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "match_id" uuid NOT NULL, "player_id" uuid NOT NULL, "runs_given" integer NOT NULL, "four_given" integer NOT NULL, "six_given" integer NOT NULL, "balls_bowled" integer NOT NULL, "wicket" integer NOT NULL, "dot_balls" integer NOT NULL, "maidian_over" integer NOT NULL, "is_ball" text NOT NULL, PRIMARY KEY ("id") , FOREIGN KEY ("match_id") REFERENCES "Players"."Matches"("id") ON UPDATE restrict ON DELETE restrict, FOREIGN KEY ("player_id") REFERENCES "Players"."Players"("id") ON UPDATE restrict ON DELETE restrict);COMMENT ON TABLE "Players"."Bowling_stats" IS E'All Bowling Stats';
CREATE EXTENSION IF NOT EXISTS pgcrypto;
